export default function ActiveHrs(props) {
  //static demoUrl = 'https://codesandbox.io/s/simple-line-chart-kec3v';
var DATA=[]
props.dat.datasets[0].data.map((e,index)=>{DATA.push({name:props.dat.labels[index],"articles sold":e})})

    return (
      <ResponsiveContainer width="100%" height="90%">
        <Title>Active Hours</Title>
        <LineChart
          width={500}
          height={300}
          data={DATA}
          margin={{
            top: 5,
            right: 30,
            left: 20,
            bottom: 5,
          }}
        >
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="name" />
          <YAxis />
          <Tooltip />
          <Legend />
         {/* <Line type="monotone" dataKey="pv" stroke="#8884d8" activeDot={{ r: 8 }} /> */}
          <Line type="monotone" dataKey="articles sold" stroke="#ffc658" />
        </LineChart>
      </ResponsiveContainer>
    );
  
}
